Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include<bits/stdc++.h>
using  namespace std;
#define fi first
#define se second
#define pb push_back
#define eb emplace_back
#define mp make_pair
#define sz(x) ((ll)(x).size())
#define init(x, a) memset(x, a, sizeof(x))
#define forr(i,a,b) for(ll i=(ll)a;i<(ll)b;i++)
#define rfor(i,a,b) for(ll i=(ll)a;i>=(ll)b;i--)
#define fastio ios_base::sync_with_stdio(false);cin.tie(0);cout.tie(0)
typedef  long long ll;
typedef long double ld;
typedef pair<ll,ll> pll;
typedef vector<ll> vll;
typedef set<ll> sll;
typedef unordered_set<ll> usll;
typedef map<ll,ll> mll;
typedef unordered_map<ll,ll> umll;
//const ll mod = 1e6+3;
//const ld PI=3.14159265;
ll gcd(ll a,ll b) { return a?gcd(b%a,a):b;}

int main()
{
    fastio;
    int r=0,k=0;
    string s,ans="";
    cin>>s;
    ans+=s[0];
    forr(i,1,sz(s))
    {
        r=0;
        if(s[i]=='d'&& i+3<sz(s))
        {
            if(s[i+1]=='o' && s[i+2]=='t'){ans+='.';i+=2;r=1;}
        }
        if(s[i]=='a' && i+1<sz(s) && k==0)
        {
            if(s[i+1]=='t'){ans+='@';i+=1;r=1;k=1;}
        }
        if(r==0)
        {
            ans+=s[i];
        }
    }
    cout<<ans;
    return 0;
}
